    'gym.wrongWay':'\u0917\u0932\u0924 \u0926\u093f\u0936\u093e\u0924\u093f\u0930',
    'gym.steady':'\u0938\u094d\u0925\u093f\u0930 \u1f4aa',
    'gym.drift':'\u092c\u0939\u0915\u093f\u0901\u0926\u0948 \u2014 \u0915\u0938\u094d\u0928\u0941\u0939\u094b\u0938\u094d',
    'gym.focus':'\u092f\u0938\u092e\u093e \u0915\u093e\u092e \u0917\u0930\u094d\u0928\u0941\u0939\u094b\u0938\u094d',
