    'gym.nEntries':'{n} \u0924\u094c\u0932 \u092a\u094d\u0930\u0935\u093f\u0937\u094d\u091f\u093f',
    'gym.tipWeigh':'\u0939\u092a\u094d\u0924\u093e\u092e\u093e \u0915\u092e\u094d\u0924\u0940\u092e\u093e \u090f\u0915\u092a\u091f\u0915 \u0924\u094c\u0932 \u0928\u093e\u092a\u094d\u0928\u0941\u0939\u094b\u0938\u094d \u2014 \u091f\u094d\u0930\u0947\u0928\u094d\u0921 \u090f\u0915\u0926\u093f\u0928\u0947 \u0928\u093e\u092a\u092d\u0928\u094d\u0926\u093e \u092d\u0930\u092a\u0930\u094d\u0926\u094b\u0964',
    'gym.tipWaist':'\u0915\u092e\u094d\u092e\u0930 \u092a\u0928\u093f \u0932\u0917 \u0917\u0930\u094d\u0928\u0941\u0939\u094b\u0938\u094d, \u0924\u094c\u0932 \u0905\u0921\u094d\u0915\u093f\u0901\u0926\u093e \u092a\u0928\u093f \u092c\u094b\u0938\u094b \u0918\u091f\u0947\u0915\u094b \u0926\u0947\u0916\u093f\u0928\u094d\u091b\u0964',
    'gym.tipCut':'\u0924\u092a\u093e\u0908\u0902 \u0905\u091d\u0948 \u0915\u091f\u093f\u0919\u092e\u093e \u0939\u0941\u0928\u0941\u0939\u0941\u0928\u094d\u091b \u2014 \u092e\u093e\u0902\u0938\u092a\u0947\u0936\u0940 \u091c\u094b\u0917\u093e\u0909\u0928 \u092a\u094d\u0930\u094b\u091f\u093f\u0928 \u0909\u091a\u094d\u091a \u0930\u093e\u0916\u094d\u0928\u0941\u0939\u094b\u0938\u094d\u0964',
    'gym.tipBulk':'\u092c\u0922\u0947\u0915\u094b \u092a\u094d\u0930\u093e\u092f\u0903 \u092c\u094b\u0938\u094b \u0939\u094b \u092d\u0928\u0947 \u0938\u0930\u092a\u094d\u0932\u0938 \u0905\u0932\u093f \u0918\u091f\u093e\u0909\u0928\u0941\u0939\u094b\u0938\u094d \u2014 \u0910\u0928\u093e \u0930 \u0915\u092e\u094d\u092e\u0930 \u0939\u0947\u0930\u094d\u0928\u0941\u0939\u094b\u0938\u094d\u0964',
