    'gym.iBmiT':'\u092c\u0949\u0921\u0940 \u092e\u093e\u0938 \u0907\u0902\u0921\u0947\u0915\u094d\u0938 \u2014 \u090a\u0902\u091a\u093e\u0908 \u0915\u0947 \u0905\u0928\u0941\u092a\u093e\u0924 \u092e\u0947\u0902 \u0935\u091c\u093c\u0928\u0964 \u092e\u094b\u091f\u093e \u0905\u0928\u0941\u092e\u093e\u0928, \u092b\u0948\u0938\u0932\u093e \u0928\u0939\u0940\u0902: \u092e\u093e\u0902\u0938\u0932 \u0932\u094b\u0917\u094b\u0902 \u0915\u093e "\u0905\u0927\u093f\u0915 \u0935\u091c\u093c\u0928" \u0906 \u0938\u0915\u0924\u093e \u0939\u0948 \u091c\u092c\u0915\u093f \u0935\u0947 \u0932\u0940\u0928 \u0939\u094b\u0902\u0964',
    'gym.iBf':'\u092c\u0949\u0921\u0940-\u092b\u0948\u091f \u0905\u0928\u0941\u092e\u093e\u0928 \u0915\u0947 \u092c\u093e\u0930\u0947 \u092e\u0947\u0902',
    'gym.iBfT':'\u0905\u092e\u0947\u0930\u093f\u0915\u0940 \u0928\u0947\u0935\u0940 \u091f\u0947\u092a \u0935\u093f\u0927\u093f \u0938\u0947 \u0905\u0928\u0941\u092e\u093e\u0928 (\u0917\u0930\u094d\u0926\u0928, \u0915\u092e\u0930, \u090a\u0902\u091a\u093e\u0908)\u0964 \u091c\u093c\u094d\u092f\u093e\u0926\u093e\u0924\u0930 \u0932\u094b\u0917\u094b\u0902 \u0915\u0947 \u0932\u093f\u090f \u0915\u0941\u091b \u092a\u094d\u0930\u0924\u093f\u0936\u0924 \u0915\u0947 \u092d\u0940\u0924\u0930 \u0938\u0939\u0940 \u2014 DEXA \u0938\u094d\u0915\u0948\u0928 \u0938\u092c\u0938\u0947 \u0938\u091f\u0940\u0915\u0964',
    'gym.iProtein':'\u0907\u0924\u0928\u093e \u092a\u094d\u0930\u094b\u091f\u0940\u0928 \u0915\u094d\u092f\u094b\u0902?',
    'gym.iProteinT':'\u0916\u0947\u0932 \u092a\u094b\u0937\u0923 \u0905\u0928\u0941\u0938\u0902\u0927\u093e\u0928 \u0915\u0947 \u0905\u0928\u0941\u0938\u093e\u0930 \u092e\u0938\u0932 \u092c\u0928\u093e\u0928\u0947/\u092c\u091a\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0930\u094b\u091c\u093c \u0936\u0930\u0940\u0930 \u0915\u0947 \u0935\u091c\u093c\u0928 \u0915\u0947 \u092a\u094d\u0930\u0924\u093f \u0915\u093f\u0932\u094b 1.6\u20132.2 \u0917\u094d\u0930\u093e\u092e \u092a\u094d\u0930\u094b\u091f\u0940\u0928\u0964 3\u20135 \u092d\u094b\u091c\u0928 \u092e\u0947\u0902 \u092c\u093e\u0902\u091f\u0947\u0902\u0964',
    'gym.mealsT':'\u092b\u094d\u092f\u0942\u0932 \u0926\u093f\u0928: {g}',
    'gym.mealsSub':'\u2248 \u092e\u0924\u0932\u092c \u0905\u0928\u0941\u092e\u093e\u0928\u0964 \u092a\u0939\u0932\u0947 \u092a\u094d\u0930\u094b\u091f\u0940\u0928 \u0932\u0915\u094d\u0937\u094d\u092f \u092a\u0942\u0930\u093e \u0915\u0930\u0947\u0902 \u2014 \u092b\u093f\u0930 \u0915\u0948\u0932\u094b\u0930\u0940\u0964',
