    'gym.evening':'\u0936\u093e\u092e',
    'gym.mLoseB':'\u0917\u094d\u0930\u0940\u0915 \u0926\u0939\u0940 \u092c\u093e\u0909\u0932 \u2014 \u0926\u0939\u0940, \u092c\u0947\u0930\u0940, 1 \u091a\u092e\u094d\u092e\u091a \u0936\u0939\u0926 \u00b7 \u2248320 \u0915\u0948\u0932\u094b\u0930\u0940 \u00b7 28\u0917\u094d\u0930\u093e \u092a\u094d\u0930\u094b\u091f\u0940\u0928',
    'gym.mLoseL':'\u0917\u094d\u0930\u093f\u0932\u094d\u0921 \u091a\u093f\u0915\u0928 \u0938\u0932\u093e\u0926 \u2014 \u091a\u093f\u0915\u0928 \u092c\u094d\u0930\u0947\u0938\u094d\u091f, \u0939\u0930\u0940 \u0938\u092c\u094d\u091c\u093c\u093f\u092f\u093e\u0902, \u091c\u0948\u0924\u0942\u0928 \u0924\u0947\u0932 + \u0928\u0940\u0902\u092c\u0942 \u00b7 \u2248450 \u0915\u0948\u0932\u094b\u0930\u0940 \u00b7 40\u0917\u094d\u0930\u093e \u092a\u094d\u0930\u094b\u091f\u0940\u0928',
    'gym.mLoseP':'\u0915\u0947\u0932\u093e + \u092c\u094d\u0932\u0948\u0915 \u0915\u0949\u092b\u093c\u0940 \u00b7 \u2248105 \u0915\u0948\u0932\u094b\u0930\u0940',
    'gym.mLoseD':'\u092c\u0947\u0915\u094d\u0921 \u0938\u092b\u093c\u0947\u0926 \u092e\u091b\u0932\u0940 + \u092c\u094d\u0930\u094b\u0915\u0932\u0940 + \u00bd \u0915\u092a \u091a\u093e\u0935\u0932 \u00b7 \u2248480 \u0915\u0948\u0932\u094b\u0930\u0940 \u00b7 38\u0917\u094d\u0930\u093e \u092a\u094d\u0930\u094b\u091f\u0940\u0928',
    'gym.mLoseE':'\u0915\u0949\u091f\u0947\u091c \u091a\u0940\u091c\u093c + \u0926\u093e\u0932\u091a\u0940\u0928\u0940 \u00b7 \u2248180 \u0915\u0948\u0932\u094b\u0930\u0940 \u00b7 20\u0917\u094d\u0930\u093e \u092a\u094d\u0930\u094b\u091f\u0940\u0928',
    'gym.mMaintainB':'\u0913\u091f\u092e\u0940\u0932 + \u092a\u0940\u0928\u091f \u092c\u091f\u0930 + \u0915\u0947\u0932\u093e \u00b7 \u2248520 \u0915\u0948\u0932\u094b\u0930\u0940 \u00b7 18\u0917\u094d\u0930\u093e \u092a\u094d\u0930\u094b\u091f\u0940\u0928',
    'gym.mMaintainL':'\u091a\u093f\u0915\u0928 \u0930\u093e\u0907\u0938 \u092c\u093e\u0909\u0932 \u2014 \u091a\u093f\u0915\u0928, 1 \u0915\u092a \u091a\u093e\u0935\u0932, \u0938\u092c\u094d\u091c\u093c\u093f\u092f\u093e\u0902 \u00b7 \u2248650 \u0915\u0948\u0932\u094b\u0930\u0940 \u00b7 45\u0917\u094d\u0930\u093e \u092a\u094d\u0930\u094b\u091f\u0940\u0928',
    'gym.mMaintainP':'\u0938\u0947\u092c + \u092e\u0941\u091f\u094d\u0920\u0940\u092d\u0930 \u092c\u093e\u0926\u093e\u092e \u00b7 \u2248220 \u0915\u0948\u0932\u094b\u0930\u0940 \u00b7 6\u0917\u094d\u0930\u093e \u092a\u094d\u0930\u094b\u091f\u0940\u0928',
