    'gym.mMaintainE':'\u0917\u094d\u0930\u0940\u0915 \u0926\u0939\u0940 + \u0917\u094d\u0930\u093e\u0928\u094b\u0932\u093e \u00b7 \u2248280 \u0915\u0948\u0932\u094b\u0930\u0940 \u00b7 18\u0917\u094d\u0930\u093e \u092a\u094d\u0930\u094b\u091f\u0940\u0928',
    'gym.mGainB':'\u092c\u0921\u093c\u093e \u0913\u0935\u0930\u0928\u093e\u0907\u091f \u0913\u091f\u094d\u0938 \u2014 \u0913\u091f\u094d\u0938, \u0926\u0942\u0927, whey, \u092a\u0940\u0928\u091f \u092c\u091f\u0930, \u0915\u0947\u0932\u093e \u00b7 \u2248750 \u0915\u0948\u0932\u094b\u0930\u0940 \u00b7 40\u0917\u094d\u0930\u093e \u092a\u094d\u0930\u094b\u091f\u0940\u0928',
    'gym.mGainL':'\u092e\u0940\u091f + 1.5 \u0915\u092a \u091a\u093e\u0935\u0932 + \u0938\u092c\u094d\u091c\u093c\u093f\u092f\u093e\u0902 \u00b7 \u2248800 \u0915\u0948\u0932\u094b\u0930\u0940 \u00b7 50\u0917\u094d\u0930\u093e \u092a\u094d\u0930\u094b\u091f\u0940\u0928',
