    'gym.mGainD':'\u091a\u093f\u0915\u0928 \u092a\u093e\u0938\u094d\u0924\u093e \u2014 \u092a\u093e\u0938\u094d\u0924\u093e, \u091a\u093f\u0915\u0928, \u091f\u092e\u093e\u091f\u0930 \u0938\u0949\u0938, \u092a\u093e\u0930\u094d\u092e\u0947\u0938\u0928 \u00b7 \u2248850 \u0915\u0948\u0932\u094b\u0930\u0940 \u00b7 55\u0917\u094d\u0930\u093e \u092a\u094d\u0930\u094b\u091f\u0940\u0928',
    'gym.mGainE':'\u0917\u094d\u0930\u0940\u0915 \u0926\u0939\u0940 + \u0917\u094d\u0930\u093e\u0928\u094b\u0932\u093e + \u0936\u0939\u0926 \u00b7 \u2248400 \u0915\u0948\u0932\u094b\u0930\u0940 \u00b7 25\u0917\u094d\u0930\u093e \u092a\u094d\u0930\u094b\u091f\u0940\u0928',
