    'gym.r1i':'80\u0917\u094d\u0930\u093e \u0913\u091f\u094d\u0938, 250\u092e\u093f\u0932\u0940 \u0926\u0942\u0927, 1 \u0938\u094d\u0915\u0942\u092a whey, 1 \u091a\u092e\u094d\u092e\u091a \u092a\u0940\u0928\u091f \u092c\u091f\u0930, \u00bd \u0915\u091f\u093e \u0915\u0947\u0932\u093e',
    'gym.r1s':'1. \u0915\u0947\u0932\u0947 \u0915\u094b \u091b\u094b\u0921\u093c\u0915\u0930 \u0938\u092c \u0915\u0941\u091b \u091c\u093e\u0930 \u092e\u0947\u0902 \u092e\u093f\u0932\u093e\u090f\u0902\u0964 2. \u0930\u093e\u0924\u092d\u0930 \u092b\u094d\u0930\u093f\u091c \u092e\u0947\u0902 \u0930\u0916\u0947\u0902\u0964 3. \u0938\u0941\u092c\u0939 \u0915\u0947\u0932\u093e \u0921\u093e\u0932\u0915\u0930 \u0916\u093e\u090f\u0902\u0964',
