    'gym.r2s':'1. \u091a\u093f\u0915\u0928 \u092e\u0947\u0902 \u0928\u092e\u0915, \u0915\u093e\u0932\u0940 \u092e\u093f\u0930\u094d\u091a, \u0932\u0939\u0938\u0941\u0928 \u0932\u0917\u093e\u090f\u0902\u0964 2. \u0939\u0930 \u0924\u0930\u092b 6\u20137 \u092e\u093f\u0928\u091f \u0938\u0947\u0915\u0947\u0902 \u091c\u092c \u0924\u0915 \u092a\u0915 \u091c\u093e\u090f\u0964 3. \u091a\u093e\u0935\u0932 \u0914\u0930 \u0938\u092c\u094d\u091c\u093c\u093f\u092f\u094b\u0902 \u092a\u0930 \u0915\u093e\u091f\u0915\u0930 \u0930\u0916\u0947\u0902, \u0938\u094b\u092f\u093e \u0938\u0949\u0938 \u0921\u093e\u0932\u0947\u0902\u0964',
