    'gym.r3t':'\u092e\u0938\u0942\u0930 \u0926\u093e\u0932 + \u091a\u093e\u0935\u0932',
    'gym.r3i':'1 \u0915\u092a \u092e\u0938\u0942\u0930 \u0926\u093e\u0932, 1 \u092a\u094d\u092f\u093e\u091c\u093c, 1 \u091f\u092e\u093e\u091f\u0930, \u0939\u0932\u094d\u0926\u0940, \u091c\u0940\u0930\u093e, 1 \u0915\u092a \u091a\u093e\u0935\u0932',
    'gym.r3s':'1. \u092a\u094d\u092f\u093e\u091c\u093c \u092d\u0942\u0928\u0947\u0902, \u091f\u092e\u093e\u091f\u0930 \u0914\u0930 \u092e\u0938\u093e\u0932\u0947 \u0921\u093e\u0932\u0947\u0902\u0964 2. \u0926\u093e\u0932 + 3 \u0915\u092a \u092a\u093e\u0928\u0940 \u0921\u093e\u0932\u0915\u0930 20 \u092e\u093f\u0928\u091f \u092a\u0915\u093e\u090f\u0902\u0964 3. \u091a\u093e\u0935\u0932 \u0915\u0947 \u0938\u093e\u0925 \u092a\u0930\u094b\u0938\u0947\u0902\u0964',
    'gym.r3n':'\u2248550 \u0915\u0948\u0932\u094b\u0930\u0940 \u00b7 22\u0917\u094d\u0930\u093e \u092a\u094d\u0930\u094b\u091f\u0940\u0928',
    'gym.r4t':'\u0932\u0940\u0928 \u091a\u093f\u0915\u0928 \u0938\u0932\u093e\u0926',
    'gym.r4i':'150\u0917\u094d\u0930\u093e \u0917\u094d\u0930\u093f\u0932\u094d\u0921 \u091a\u093f\u0915\u0928, \u092e\u093f\u0932\u0940-\u091c\u0941\u0932\u0940 \u0939\u0930\u0940 \u0938\u092c\u094d\u091c\u093c\u093f\u092f\u093e\u0902, \u00bd \u0916\u0940\u0930\u093e, 1 \u091a\u092e\u094d\u092e\u091a \u091c\u0948\u0924\u0942\u0928 \u0924\u0947\u0932, \u0928\u0940\u0902\u092c\u0942 \u0930\u0938',
    'gym.r4s':'1. \u0938\u092c \u0915\u0941\u091b \u0915\u093e\u091f\u0915\u0930 \u092c\u093e\u0909\u0932 \u092e\u0947\u0902 \u0921\u093e\u0932\u0947\u0902\u0964 2. \u0924\u0947\u0932 + \u0928\u0940\u0902\u092c\u0942 + \u0928\u092e\u0915 \u092e\u093f\u0932\u093e\u0915\u0930 \u0921\u094d\u0930\u0947\u0938\u093f\u0902\u0917 \u092c\u0928\u093e\u090f\u0902\u0964 3. \u092e\u093f\u0932\u093e\u0915\u0930 \u0924\u093e\u091c\u093c\u093e \u0916\u093e\u090f\u0902\u0964',
    'gym.r4n':'\u2248400 \u0915\u0948\u0932\u094b\u0930\u0940 \u00b7 40\u0917\u094d\u0930\u093e \u092a\u094d\u0930\u094b\u091f\u0940\u0928',
    'gym.r5t':'टर्की चिली',
    'gym.r5i':'250g लीन पिसा हुआ टर्की, 1 कैन राजमा, 1 कैन कटे हुए टमाटर, 1 प्याज़, मिर्च पाउडर, जीरा',
    'gym.r5s':'1. टर्की को प्याज़ के साथ भूनें। 2. राजमा, टमाटर और मसाले डालें। 3. 25 मिनट तक धीमी आंच पर पकाएं, गरम परोसें।',
    'gym.r5n':'≈580 kcal · 42g प्रोटीन',
    'gym.suppNote':'\u0938\u092a\u094d\u0932\u0940\u092e\u0947\u0902\u091f \u0906\u0916\u093f\u0930\u0940 5% \u0939\u0948\u0902\u0964 \u091f\u094d\u0930\u0947\u0928\u093f\u0902\u0917, \u0916\u093e\u0928\u093e \u0914\u0930 \u0928\u0940\u0902\u0926 \u092c\u093e\u0915\u0940 \u0915\u0930\u0924\u0940 \u0939\u0948\u0964 \u092f\u0939 \u091a\u093f\u0915\u093f\u0924\u094d\u0938\u093e \u0938\u0932\u093e\u0939 \u0928\u0939\u0940\u0902 \u0939\u0948 \u2014 \u0936\u0941\u0930\u0942 \u0915\u0930\u0928\u0947 \u0938\u0947 \u092a\u0939\u0932\u0947 \u0915\u094b\u091a \u092f\u093e \u0921\u0949\u0915\u094d\u091f\u0930 \u0938\u0947 \u092a\u0942\u091b\u0947\u0902\u0964',
    'gym.creatine':'\u0915\u094d\u0930\u093f\u090f\u091f\u093f\u0928 \u092e\u094b\u0928\u094b\u0939\u093e\u0907\u0921\u094d\u0930\u0947\u091f',
    'gym.creatineT':'\u0926\u0941\u0928\u093f\u092f\u093e \u0915\u093e \u0938\u092c\u0938\u0947 \u091c\u093c\u094d\u092f\u093e\u0926\u093e \u0905\u0927\u094d\u092f\u092f\u0928 \u0915\u093f\u092f\u093e \u0917\u092f\u093e \u0938\u094d\u092a\u094b\u0930\u094d\u091f\u094d\u0938 \u0938\u092a\u094d\u0932\u0940\u092e\u0947\u0902\u091f\u0964 \u0930\u094b\u091c\u093c 3\u20135 \u0917\u094d\u0930\u093e\u092e \u0939\u092b\u093c\u094d\u0924\u094b\u0902 \u0915\u0940 \u091f\u094d\u0930\u0947\u0928\u093f\u0902\u0917 \u092e\u0947\u0902 \u0924\u093e\u0915\u0924 \u0914\u0930 \u092a\u093e\u0935\u0930 \u0925\u094b\u0921\u093c\u093e \u092c\u0922\u093c\u093e \u0938\u0915\u0924\u093e \u0939\u0948\u0964 \u0938\u092e\u092f \u0938\u0947 \u091c\u093c\u094d\u092f\u093e\u0926\u093e \u092b\u0930\u094d\u0915 \u0928\u0939\u0940\u0902 \u092a\u0921\u093c\u0924\u093e \u2014 \u0930\u094b\u091c\u093c \u0915\u0940 \u0928\u093f\u0930\u0902\u0924\u0930\u0924\u093e \u092e\u093e\u092f\u0928\u0947 \u0930\u0916\u0924\u0940 \u0939\u0948\u0964 \u092f\u0939 \u092e\u093e\u0902\u0938\u092a\u0947\u0936\u093f\u092f\u094b\u0902 \u092e\u0947\u0902 \u092a\u093e\u0928\u0940 \u0916\u0940\u0902\u091a\u0924\u093e \u0939\u0948, \u0907\u0938\u0932\u093f\u090f \u0936\u0941\u0930\u0941\u0906\u0924 \u092e\u0947\u0902 \u0935\u091c\u093c\u0928 1\u20132 \u0915\u093f\u0932\u094b \u092c\u0922\u093c \u0938\u0915\u0924\u093e \u0939\u0948 (\u0935\u0939 \u092a\u093e\u0928\u0940 \u0939\u0948, \u092b\u0948\u091f \u0928\u0939\u0940\u0902)\u0964 \u092f\u0939 \u0938\u094d\u091f\u0947\u0930\u0949\u092f\u0921 \u0928\u0939\u0940\u0902 \u0939\u0948\u0964 \u0916\u0942\u092c \u092a\u093e\u0928\u0940 \u092a\u093f\u090f\u0902, \u0932\u094b\u0921\u093f\u0902\u0917 \u092b\u0947\u091c\u093c \u091b\u094b\u0921\u093c\u0947\u0902, \u0914\u0930 \u0915\u093f\u0921\u0928\u0940 \u0915\u0940 \u0938\u092e\u0938\u094d\u092f\u093e \u0939\u094b \u0924\u094b \u092a\u0939\u0932\u0947 \u0921\u0949\u0915\u094d\u091f\u0930 \u0938\u0947 \u092c\u093e\u0924 \u0915\u0930\u0947\u0902\u0964',
    'gym.whey':'\u0935\u094d\u0939\u0947 \u092a\u094d\u0930\u094b\u091f\u0940\u0928',
    'gym.wheyT':'\u092c\u0938 \u0938\u0941\u0935\u093f\u0927\u093e\u091c\u0928\u0915 \u092a\u094d\u0930\u094b\u091f\u0940\u0928 \u2014 \u092a\u094d\u0930\u0924\u093f \u0938\u094d\u0915\u0942\u092a \u0932\u0917\u092d\u0917 25 \u0917\u094d\u0930\u093e\u092e\u0964 \u092f\u0939 \u0905\u0915\u0947\u0932\u0947 \u092e\u0938\u0932 \u0928\u0939\u0940\u0902 \u092c\u0928\u093e\u0924\u093e; \u091f\u094d\u0930\u0947\u0928\u093f\u0902\u0917 + \u0926\u093f\u0928\u092d\u0930 \u0915\u093e \u0915\u0941\u0932 \u092a\u094d\u0930\u094b\u091f\u0940\u0928 \u092c\u0928\u093e\u0924\u093e \u0939\u0948\u0964 \u0935\u0930\u094d\u0915\u0906\u0909\u091f \u0915\u0947 \u092c\u093e\u0926 \u092f\u093e \u091c\u092c \u0916\u093e\u0928\u093e \u0928 \u092c\u0928\u093e \u0938\u0915\u0947\u0902, \u0924\u092c \u0909\u092a\u092f\u094b\u0917\u0940\u0964 \u0926\u0942\u0927 \u0938\u0947 \u0926\u093f\u0915\u094d\u0915\u0924 \u0939\u094b \u0924\u094b isolate \u0906\u091c\u093c\u092e\u093e\u090f\u0902\u0964 \u092b\u094d\u0932\u0947\u0935\u0930\u094d\u0921 \u092a\u093e\u0909\u0921\u0930 \u092e\u0947\u0902 \u091b\u093f\u092a\u0940 \u091a\u0940\u0928\u0940 \u0926\u0947\u0916\u0947\u0902\u0964 \u092a\u0939\u0932\u0947 \u0916\u093e\u0928\u093e, \u092b\u093f\u0930 \u092a\u093e\u0909\u0921\u0930\u0964',
