    'gym.noDataHint':'\u0939\u0930 \u0939\u092b\u093c\u094d\u0924\u0947 \u090f\u0915 \u0939\u0940 \u0938\u092e\u092f \u092a\u0930 \u0935\u091c\u093c\u0928 \u0915\u0930\u0915\u0947 \u092f\u0939\u093e\u0902 \u0926\u0930\u094d\u091c \u0915\u0930\u0947\u0902\u0964',
