    'gym.tipWeigh':'\u0939\u092b\u093c\u094d\u0924\u0947 \u092e\u0947\u0902 \u0915\u092e \u0938\u0947 \u0915\u092e \u090f\u0915 \u092c\u093e\u0930 \u0935\u091c\u093c\u0928 \u0915\u0930\u0947\u0902 \u2014 \u091f\u094d\u0930\u0947\u0902\u0921 \u090f\u0915 \u0926\u093f\u0928 \u0938\u0947 \u092c\u0947\u0939\u0924\u0930\u0964',
    'gym.tipWaist':'\u0915\u092e\u0930 \u092d\u0940 \u0926\u0930\u094d\u091c \u0915\u0930\u0947\u0902, \u0924\u093e\u0915\u093f \u0935\u091c\u093c\u0928 \u0905\u091f\u0915\u0947 \u0924\u092c \u092d\u0940 \u092b\u0948\u091f \u0918\u091f\u0924\u093e \u0926\u093f\u0916\u0947\u0964',
    'gym.tipCut':'\u0906\u092a \u0905\u092d\u0940 \u0915\u091f\u093f\u0902\u0917 \u092e\u0947\u0902 \u0939\u0948\u0902 \u2014 \u092e\u0938\u0932 \u092c\u091a\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u094d\u0930\u094b\u091f\u0940\u0928 \u091c\u093c\u094d\u092f\u093e\u0926\u093e \u0930\u0916\u0947\u0902\u0964',
    'gym.tipBulk':'\u092c\u0922\u093c\u0924 \u091c\u093c\u094d\u092f\u093e\u0926\u093e\u0924\u0930 \u092b\u0948\u091f \u0939\u094b \u0924\u094b \u0938\u0930\u092a\u094d\u0932\u0938 \u0925\u094b\u0921\u093c\u093e \u0918\u091f\u093e\u090f\u0902 \u2014 \u0906\u0908\u0928\u093e \u0914\u0930 \u0915\u092e\u0930 \u0926\u0947\u0916\u0947\u0902\u0964',
