/* ================= welcome flow + pickers + static application ================= */
(function(){
'use strict';
var i18n=HUB.i18n;
var t=i18n.t;
/* Picker region order: Global first, then roughly west→east.
   (Declared here: listHTML below lives in this IIFE; the first IIFE's
   REGION_ORDER is a different scope and not visible here.) */
var REGION_ORDER=['Global','Europe','Europe & Latin America','Europe & Central Asia','Middle East & Europe','Middle East & North Africa','Middle East','Africa','South Asia','Southeast Asia','East Asia'];

/* ---- applyStatic: translate index.html chrome via data-i18n attributes ---- */
function applyStatic(){
  document.querySelectorAll('[data-i18n]').forEach(function(el){
    el.textContent=t(el.getAttribute('data-i18n'));
  });
  document.querySelectorAll('[data-i18n-aria]').forEach(function(el){
    el.setAttribute('aria-label',t(el.getAttribute('data-i18n-aria')));
  });
  document.querySelectorAll('[data-i18n-ph]').forEach(function(el){
    el.setAttribute('placeholder',t(el.getAttribute('data-i18n-ph')));
  });
  var title=document.querySelector('title');
  if(title) title.textContent=t('app.title');
  document.documentElement.lang=i18n.getLang();
  i18n.applyDir(i18n.getLang());
}

/* ---- language picker sheet (globe button + settings) ----
   Searchable + region-grouped so ~30 languages stay scannable.
   Region labels stay in English (picker metadata, per the 'हिन्दी — South Asia'
   pattern). Selecting a lazy locale shows a loading state on its row until the
   dictionary arrives; setLang then applies it without a reload. */
function langRowHTML(code,cur){
  var L=i18n.LOCALES[code];
  return '<button class="item langrow" data-lang="'+code+'" style="cursor:pointer;text-align:start;width:100%">'+
    '<div class="grow"><h3>'+esc(L.native)+'</h3><div class="meta">'+esc(L.label)+(L.region?' · '+esc(L.region):'')+'</div></div>'+
    (code===cur?'<span class="langcheck">✓</span>':'')+
  '</button>';
}
function openLanguagePicker(){
  var cur=i18n.getLang(), q='';
  function listHTML(){
    var ql=q.trim().toLowerCase();
    var codes=Object.keys(i18n.LOCALES);
    if(ql){
      /* searching: flat ranked list, fastest to scan */
      codes=codes.filter(function(code){
        var L=i18n.LOCALES[code];
        return code===ql ||
          L.native.toLowerCase().indexOf(ql)!==-1 ||
          L.label.toLowerCase().indexOf(ql)!==-1 ||
          (L.region||'').toLowerCase().indexOf(ql)!==-1;
      });
      if(!codes.length) return '<div class="empty"><p>'+t('langpicker.none')+'</p></div>';
      return codes.map(function(code){ return langRowHTML(code,cur); }).join('');
    }
    /* browsing: grouped by region */
    var byRegion={};
    codes.forEach(function(code){
      var r=i18n.LOCALES[code].region||'';
      (byRegion[r]=byRegion[r]||[]).push(code);
    });
    return REGION_ORDER.filter(function(r){ return byRegion[r]; }).map(function(r){
      var rows=byRegion[r].sort(function(a,b){
        return i18n.LOCALES[a].native.localeCompare(i18n.LOCALES[b].native);
      }).map(function(code){ return langRowHTML(code,cur); }).join('');
      return '<div class="langregion">'+esc(r)+'</div>'+rows;
    }).join('');
  }
  HUB.ui.openSheet(
    '<h2>'+t('langpicker.title')+'</h2>'+
    '<p class="sub" style="margin-bottom:12px">'+t('langpicker.sub')+'</p>'+
    '<div class="field"><input class="input" id="langSearch" placeholder="🔍 '+escAttr(t('common.search'))+'…" autocomplete="off"></div>'+
    '<div id="langList" style="max-height:52vh;overflow-y:auto"></div>'
  );
  var host=document.getElementById('langList'), inp=document.getElementById('langSearch');
  function draw(){
    host.innerHTML=listHTML(); bind();
    var ll=i18n.loadingLang(); if(ll) markLangLoading(ll,true);
  }
  function bind(){
    host.querySelectorAll('.langrow').forEach(function(b){
      b.onclick=function(){
        /* async for lazy locales: keep the sheet open, the row shows a
           spinner until setLang applies the language (which closes the sheet). */
        i18n.setLang(b.dataset.lang);
      };
    });
  }
  inp.oninput=function(){ q=inp.value; draw(); };
  draw(); inp.focus();
}

/* ---- country picker sheet (settings + welcome reuse) ---- */
function countryRowHTML(c,lang,selected){
  return '<button class="item crrow" data-cc="'+c.c+'" style="cursor:pointer;text-align:start;width:100%">'+
    '<div style="font-size:26px;flex:0 0 auto">'+c.f+'</div>'+
    '<div class="grow"><h3>'+esc(i18n.countryName(c,lang))+'</h3>'+
    (i18n.countryName(c,'en')!==i18n.countryName(c,lang)?'<div class="meta">'+esc(c.en)+'</div>':'')+'</div>'+
    (selected?'<span style="font-size:20px;color:var(--volt,#C6F135)">✓</span>':'')+
  '</button>';
}
/* country search matches every localized name field present (not just the
   original 4 locales), plus the ISO code. */
function countryMatches(c,ql){
  if(c.c.toLowerCase()===ql) return true;
  for(var k in c){
    if(k==='c'||k==='f') continue;
    if(String(c[k]).toLowerCase().indexOf(ql)!==-1) return true;
  }
  return false;
}
function openCountryPicker(onPick){
  var lang=i18n.getLang(), cur=i18n.getCountry()||i18n.guessCountry(), q='';
  function listHTML(){
    var ql=q.trim().toLowerCase();
    var list=i18n.COUNTRIES.filter(function(c){
      if(!ql) return true;
      return countryMatches(c,ql);
    });
    if(!list.length) return '<div class="empty"><div class="big">🌍</div><p>'+t('countrypicker.none')+'</p></div>';
    return list.map(function(c){ return countryRowHTML(c,lang,c.c===cur); }).join('');
  }
  HUB.ui.openSheet(
    '<h2>'+t('countrypicker.title')+'</h2>'+
    '<p class="sub" style="margin-bottom:12px">'+t('countrypicker.sub')+'</p>'+
    '<div class="field"><input class="input" id="cpSearch" placeholder="'+escAttr(t('countrypicker.search'))+'" autocomplete="off"></div>'+
    '<div id="cpList" style="max-height:46vh;overflow-y:auto"></div>'+
    '<p class="hint" style="margin-top:10px">'+t('intl.currencyNote')+'</p>'
  );
  var host=document.getElementById('cpList'), inp=document.getElementById('cpSearch');
  function draw(){ host.innerHTML=listHTML(); bind(); }
  function bind(){
    host.querySelectorAll('.crrow').forEach(function(b){
      b.onclick=function(){
        i18n.setCountry(b.dataset.cc);
        HUB.ui.closeSheet();
        if(onPick) onPick(b.dataset.cc);
      };
    });
  }
  inp.oninput=function(){ q=inp.value; draw(); };
  draw(); inp.focus();
}

/* ---- welcome overlay: post-launch, pre-auth country + language ----
   Own fixed root (unhidden by itself), [hidden] guard in CSS.
   Defaults pre-selected: language English, country best-guess (or US).
   Continue works immediately — lightweight and skippable-sane. */
var wlcmLang='en', wlcmCountry='US', wlcmQ='', wlcmLQ='', wlcmStep='lang';
function ensureWelcome(next){
  var s={};
  try{ s=JSON.parse(localStorage.getItem('orbit_i18n')||'{}'); }catch(e){}
  if(s.lang&&s.country){ next(); return; } /* returning user: skip */
  wlcmLang=i18n.getLang()||'en';
  wlcmCountry=i18n.getCountry()||i18n.guessCountry();
  wlcmQ=''; wlcmLQ=''; wlcmStep='lang';
  buildWelcome(next);
}
function buildWelcome(next){
  var old=document.getElementById('wlcmHost');
  if(old) old.remove();
  var host=document.createElement('div');
  host.className='wlcmhost'; host.id='wlcmHost'; host.hidden=true;
  host.innerHTML='<div class="wlcm-card" role="dialog" aria-modal="true" aria-label="'+t('welcome.title').replace(/"/g,'&quot;')+'">'+
    '<div class="wlcm-brand"><span class="brand-name" role="img" aria-label="Onaro"><span class="brand-mark">'+HUB.icons.logoMark('W')+'</span>naro</span></div>'+
    '<div id="wlcmBody"></div>'+
  '</div>';
  document.body.appendChild(host);
  try{ if(HUB.icons&&HUB.icons.freezeLogos) HUB.icons.freezeLogos(); }catch(e){}
  drawWelcome(next);
  host.hidden=false; /* unhide own root */
}
/* ---- welcome overlay: 3 guided steps (PraBin 2026-09-22) ----
   Step 1 (lang): tap a language → the language screen disappears and the
   country dialog appears. Step 2 (country): tap a country → the dialog
   disappears and Continue appears; Back returns to Step 1. Step 3 (ready):
   friendly community disclaimer + Continue → onboarding.
   One decision per screen keeps every step inside the viewport — the old
   single-screen layout buried Continue below two scrollable lists, which is
   why users couldn't find it. */
function drawWelcome(next){
  var body=document.getElementById('wlcmBody');
  if(!body) return;
  var lang=wlcmLang;
  function T(key,vars){ /* render the welcome step in the picked language */
    var v=(HUB.i18n._dict(lang)||{})[key];
    if(v===undefined) v=HUB.i18n._dict('en')[key];
    if(v===undefined) return key;
    vars=vars||{};
    return String(v).replace(/\{(\w+)\}/g,function(m,k){ return vars[k]!==undefined?vars[k]:m; });
  }
  function stepDots(){
    var steps=['lang','country','ready'], idx=steps.indexOf(wlcmStep);
    return '<div class="wlcm-steps" aria-hidden="true">'+steps.map(function(s,i){
      return '<span class="wlcm-dot'+(i===idx?' on':'')+(i<idx?' done':'')+'"></span>';
    }).join('')+'</div>';
  }
  function langListHTML(){
    return Object.keys(i18n.LOCALES).filter(function(code){
      var q=wlcmLQ.trim().toLowerCase();
      if(!q) return true;
      var L=i18n.LOCALES[code];
      return code===q ||
        L.native.toLowerCase().indexOf(q)!==-1 ||
        L.label.toLowerCase().indexOf(q)!==-1 ||
        (L.region||'').toLowerCase().indexOf(q)!==-1;
    }).map(function(code){
      var L=i18n.LOCALES[code];
      var loading=i18n.loadingLang()===code;
      return '<button class="wlcm-lang'+(code===lang?' on':'')+(loading?' lang-loading':'')+'" data-wlang="'+code+'"'+(loading?' aria-busy="true"':'')+'>'+
        '<span class="wl">'+esc(L.native)+'</span><span class="wl-sub">'+esc(L.label)+(L.region?'<br>'+esc(L.region):'')+'</span></button>';
    }).join('') || '<div class="empty"><p>'+T('langpicker.none')+'</p></div>';
  }
  function countryListHTML(){
    var q=wlcmQ.trim().toLowerCase();
    var list=i18n.COUNTRIES.filter(function(c){
      if(!q) return true;
      return countryMatches(c,q);
    });
    return list.length?list.map(function(c){
      return '<button class="wlcm-crow'+(c.c===wlcmCountry?' on':'')+'" data-wcc="'+c.c+'">'+
        '<span class="wf">'+c.f+'</span><span class="wn">'+esc(i18n.countryName(c,lang))+'</span>'+
        (c.c===wlcmCountry?'<span class="wk">✓</span>':'')+'</button>';
    }).join(''):'<div class="empty"><div class="big">🌍</div><p>'+T('welcome.noCountryMatch')+'</p></div>';
  }
  function proceed(){
    try{ localStorage.setItem('orbit_i18n',JSON.stringify({lang:wlcmLang,country:wlcmCountry})); }catch(e){}
    document.documentElement.lang=wlcmLang;
    applyStatic();
    var h=document.getElementById('wlcmHost');
    if(h) h.hidden=true;
    next();
  }
  /* ---- Step 1: language ---- */
  if(wlcmStep==='lang'){
    body.innerHTML=stepDots()+
      '<h1>'+T('welcome.title')+'</h1>'+
      '<p class="sub" style="margin:6px 0 16px">'+T('welcome.step1Sub')+'</p>'+
      '<h2 class="wlcm-h">🌐 '+T('welcome.step1Title')+'</h2>'+
      '<div class="field" style="margin-bottom:8px"><input class="input" id="wlcmLQ" placeholder="🔍 '+escAttr(T('common.search'))+'…" autocomplete="off" value="'+escAttr(wlcmLQ)+'"></div>'+
      '<div class="wlcm-langs" style="max-height:44vh;overflow-y:auto">'+langListHTML()+'</div>';
    body.querySelectorAll('[data-wlang]').forEach(function(b){
      b.onclick=function(){
        wlcmLang=b.dataset.wlang;
        /* lazy locale: preview in English now, advance once it lands so
           Step 2 renders in the picked language. On load failure stay here
           with the tap-to-retry state (boot falls back to English anyway). */
        if(i18n.LOCALES[wlcmLang]&&i18n.LOCALES[wlcmLang].lazy&&!i18n.localeReady(wlcmLang)){
          i18n.loadLocale(wlcmLang).then(function(ok){
            if(ok){ wlcmStep='country'; }
            else{ i18n.markLangError(wlcmLang); }
            drawWelcome(next);
          });
        }else{
          wlcmStep='country';
        }
        drawWelcome(next);
      };
    });
    var lq=document.getElementById('wlcmLQ');
    lq.oninput=function(){ wlcmLQ=lq.value; var pos=lq.selectionStart; drawWelcome(next); var nl=document.getElementById('wlcmLQ'); if(nl){ nl.focus(); nl.setSelectionRange(pos,pos); } };
    return;
  }
  /* ---- Step 2: country dialog (Back returns to Step 1) ---- */
  if(wlcmStep==='country'){
    var guess=i18n.countryByCode(wlcmCountry);
    body.innerHTML=stepDots()+
      '<button class="wlcm-back" id="wlcmBack">'+escAttr(T('welcome.back'))+'</button>'+
      '<h1>'+T('welcome.step2Title')+'</h1>'+
      '<p class="sub" style="margin:6px 0 16px">'+T('welcome.step2Sub')+'</p>'+
      '<div class="field"><input class="input" id="wlcmQ" placeholder="'+escAttr(T('welcome.countrySearch'))+'" autocomplete="off" value="'+escAttr(wlcmQ)+'"></div>'+
      '<div class="wlcm-countries" style="max-height:44vh">'+countryListHTML()+'</div>'+
      (guess?'<p class="hint" style="margin-top:8px">'+guess.f+' '+esc(i18n.countryName(guess,lang))+' · '+T('welcome.guessed')+'</p>':'')+
      '<p class="hint" style="margin-top:8px">'+T('welcome.note')+'</p>';
    document.getElementById('wlcmBack').onclick=function(){ wlcmStep='lang'; drawWelcome(next); };
    body.querySelectorAll('[data-wcc]').forEach(function(b){
      b.onclick=function(){ wlcmCountry=b.dataset.wcc; wlcmStep='ready'; drawWelcome(next); };
    });
    var qi=document.getElementById('wlcmQ');
    qi.oninput=function(){ wlcmQ=qi.value; var pos=qi.selectionStart; drawWelcome(next); var nq=document.getElementById('wlcmQ'); if(nq){ nq.focus(); nq.setSelectionRange(pos,pos); } };
    return;
  }
  /* ---- Step 3: ready — pick summary + friendly disclaimer + Continue ---- */
  var L=i18n.LOCALES[wlcmLang]||{}, g2=i18n.countryByCode(wlcmCountry);
  body.innerHTML=stepDots()+
    '<h1>'+T('welcome.step3Title')+'</h1>'+
    '<p class="sub" style="margin:6px 0 16px">'+T('welcome.step3Sub')+'</p>'+
    '<div class="wlcm-picks">'+
      '<div class="wlcm-pick"><span class="wp-l">🌐</span><span class="wp-t">'+esc(L.native||wlcmLang)+'</span><button class="wp-ch" id="wlcmChLang">'+escAttr(T('welcome.change'))+'</button></div>'+
      '<div class="wlcm-pick"><span class="wp-l">'+(g2?g2.f:'🌍')+'</span><span class="wp-t">'+esc(g2?i18n.countryName(g2,lang):wlcmCountry)+'</span><button class="wp-ch" id="wlcmChCountry">'+escAttr(T('welcome.change'))+'</button></div>'+
    '</div>'+
    '<div class="wlcm-disclaimer">'+T('welcome.disclaimer')+'</div>'+
    '<button class="btn btn-primary btn-block" id="wlcmGo" style="margin-top:14px">'+T('welcome.continue')+'</button>';
  document.getElementById('wlcmChLang').onclick=function(){ wlcmStep='lang'; drawWelcome(next); };
  document.getElementById('wlcmChCountry').onclick=function(){ wlcmStep='country'; drawWelcome(next); };
  document.getElementById('wlcmGo').onclick=function(){
    var goBtn=document.getElementById('wlcmGo');
    /* lazy language still downloading: wait for it, then continue */
    if(i18n.LOCALES[wlcmLang]&&i18n.LOCALES[wlcmLang].lazy&&!i18n.localeReady(wlcmLang)){
      goBtn.disabled=true; goBtn.textContent=T('common.loading');
      i18n.loadLocale(wlcmLang).then(function(){ proceed(); });
      return;
    }
    proceed();
  };
}

/* ---- appbar chrome: globe button (visible on every tab) ---- */
function mountChrome(){
  var b=document.getElementById('langBtn');
  if(b) b.onclick=openLanguagePicker;
}

function esc(s){ return String(s==null?'':s).replace(/[&<>"']/g,function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]; }); }
function escAttr(s){ return esc(s); }

i18n.applyStatic=applyStatic;
i18n.ensureWelcome=ensureWelcome;
i18n.openLanguagePicker=openLanguagePicker;
i18n.openCountryPicker=openCountryPicker;
i18n.mountChrome=mountChrome;
})();

