Object.assign(HUB.i18n._dict('ne'),{'prof.searchClear':"खोज मेटाउनुहोस्",'prof.verifyOnly':"प्रमाणित विद्यार्थी मात्र",'prof.verifyOnlySub':"प्रमाणित विद्यार्थीले मात्र प्रोफेसरहरूलाई रेटिङ दिन सक्छन्, ताकि हरेक समीक्षा वास्तविक विद्यार्थीबाट आओस्। सहभागी हुन आफ्नो प्रोफाइल प्रमाणित गर्नुहोस्।",'prof.verifyCta':"प्रमाणित गर्नुहोस्",'prof.entryHook':"तपाईंलाई ग्रेड दिनेलाई रेट गर्नुहोस्।",'prof.entryHookSub':"आफ्नो प्रोफेसर खोज्नुहोस्, इमानदार रेटिङ दिनुहोस्, र नयाँ विद्यार्थीलाई बचाउनुहोस्।",'prof.voteSelf':"तपाईं आफ्नै टिप्पणीमा भोट दिन सक्नुहुन्न।",'prof.anon':"अज्ञात",'prof.anonNote':"तपाईंको प्रोफाइल लुकेको रहन्छ — मूल्याङ्कन वा टिप्पणीमा तपाईंको नाम कहिल्यै देखिँदैन।",'prof.cleanRule':"सम्मानजनक रहनुहोस्: गाली वा अपशब्द प्रयोग नगर्नुहोस्। हरेक टिप्पणी स्वचालित रूपमा जाँचिन्छ — आपत्तिजनक टिप्पणी हटाइन्छ, र पटक-पटक गरेमा तपाईंको खाता एक महिनाका लागि फ्ल्याग हुन्छ।",'prof.curseWarn':"कृपया अनुपयुक्त शब्दहरू हटाएर फेरि टिप्पणी गर्नुहोस्। चेतावनी {n}/३।",'prof.bannedTitle':"खाता फ्ल्याग भयो",'prof.banned':"अनुपयुक्त भाषाका कारण तपाईंको खाता फ्ल्याग गरिएको छ। {date} सम्म तपाईंले रेटिङ वा टिप्पणी गर्न सक्नुहुन्न।",'prof.addMissing':"आफ्नो प्रोफेसर भेटिएन? तिनलाई थप्न ＋ प्राध्यापक थप्नुहोस् ट्याप गर्नुहोस्।"});
Object.assign(HUB.i18n._dict('ne'),{'askg.addprof.s3':"Add professor ट्याप गर्नुहोस् र विवरण भर्नुहोस् — नाम, पद, विभाग, र कोर्सहरू।",'bdg.nextSpecNeed':"स्पेशलिस्टका लागि थप {n} समीक्षक अंक",'bdg.specDone':"स्पेशलिस्ट प्राप्त भयो — १,००० समीक्षक अंक 🌟",'bdg.specNeed':"{n}/{goal} समीक्षक अंक — स्पेशलिस्ट",'bdg.specialistD':"१,००० समीक्षक अंक। तपाईंको तह ब्याजसँगै थपिन्छ।",'bdg.tipAddProf':"कुनै प्रोफेसर छुटेको छ? २५ अंकका लागि थप्नुहोस्।",'bdg.tipReview':"Professors ट्याबमा आफ्ना प्रोफेसरहरूलाई रेटिङ र समीक्षा दिनुहोस् — हरेक समीक्षामा १० अंक।",'bdg.whySpec':"तपाईंले १,००० समीक्षक अंक कमाउनुभयो।",'prof.curseWarnAdd':"कृपया अनुपयुक्त शब्दहरू हटाएर फेरि प्रयास गर्नुहोस्। चेतावनी {n} / ३।",'prof.customTag':"एक विद्यार्थीद्वारा थपियो",'prof.fCourses':"पढाउने कोर्सहरू",'prof.fCoursesPh':"जस्तै: CS 1337, CS 4349 (कम्माले छुट्याउनुहोस्)",'prof.fTitle':"पद",'prof.fTitlePh':"जस्तै: प्रोफेसर, डा., लेक्चरर",'prof.myPoints':"तपाईंका समीक्षक अंकहरू",'prof.pts':"अंक",'prof.ptsToSpec':"स्पेशलिस्टका लागि {n} अंक बाँकी",'prof.specEarned':"स्पेशलिस्ट प्राप्त भयो 🌟",'prof.dupProf':"यो प्राध्यापक पहिले नै सूचीमा हुनुहुन्छ — मूल्याङ्कन गर्न खोज्नुहोस्।"});
Object.assign(HUB.i18n._dict('hi'),{'prof.searchClear':"खोज साफ़ करें",'prof.verifyOnly':"केवल सत्यापित छात्र",'prof.verifyOnlySub':"केवल सत्यापित छात्र ही प्रोफेसरों को रेट कर सकते हैं, ताकि हर समीक्षा असली छात्र से आए। शामिल होने के लिए अपनी प्रोफ़ाइल सत्यापित करें।",'prof.verifyCta':"सत्यापित करें",'prof.entryHook':"जिन्होंने आपको ग्रेड दिया, उन्हें रेट करें।",'prof.entryHookSub':"अपने प्रोफेसर को खोजें, ईमानदार रेटिंग दें और किसी फ्रेशर को बचाएं।",'prof.voteSelf':"आप अपनी टिप्पणी पर वोट नहीं कर सकते।",'prof.anon':"अज्ञात",'prof.anonNote':"आपकी प्रोफ़ाइल छिपी रहती है — रेटिंग या टिप्पणियों पर आपका नाम कभी नहीं दिखता।",'prof.cleanRule':"सम्मानजनक रहें: गाली या अपशब्द न लिखें। हर टिप्पणी अपने आप जाँची जाती है — आपत्तिजनक टिप्पणियाँ हटा दी जाती हैं, और बार-बार ऐसा करने पर आपका खाता एक महीने के लिए फ़्लैग हो जाता है।",'prof.curseWarn':"कृपया अनुचित शब्द हटाकर फिर से टिप्पणी करें। चेतावनी {n}/3।",'prof.bannedTitle':"खाता फ़्लैग हुआ",'prof.banned':"अनुचित भाषा के कारण आपका खाता फ़्लैग किया गया है। {date} तक आप रेट या टिप्पणी नहीं कर सकते।",'prof.addMissing':"अपना प्रोफ़ेसर नहीं मिला? उन्हें जोड़ने के लिए ＋ प्रोफ़ेसर जोड़ें दबाएँ।"});
Object.assign(HUB.i18n._dict('hi'),{'askg.addprof.s3':"प्रोफ़ेसर जोड़ें दबाएँ और उनका विवरण भरें — नाम, पद, विभाग और कोर्स।",'bdg.nextSpecNeed':"स्पेशलिस्ट के लिए {n} और रिव्यूअर पॉइंट",'bdg.specDone':"स्पेशलिस्ट मिला — 1,000 रिव्यूअर पॉइंट 🌟",'bdg.specNeed':"स्पेशलिस्ट के लिए {n}/{goal} रिव्यूअर पॉइंट",'bdg.specialistD':"1,000 रिव्यूअर पॉइंट। आपके टियर बैज के साथ जुड़ता है।",'bdg.tipAddProf':"कोई छूटा प्रोफ़ेसर जानते हैं? 25 पॉइंट के लिए उन्हें जोड़ें।",'bdg.tipReview':"प्रोफ़ेसर टैब में अपने प्रोफ़ेसरों को रेट करें और समीक्षा लिखें — हर समीक्षा पर 10 पॉइंट मिलते हैं।",'bdg.whySpec':"आपने 1,000 रिव्यूअर पॉइंट कमाए।",'prof.curseWarnAdd':"कृपया अनुचित शब्द हटाकर फिर से प्रयास करें। चेतावनी {n}/3।",'prof.customTag':"किसी छात्र द्वारा जोड़ा गया",'prof.fCourses':"पढ़ाए जाने वाले कोर्स",'prof.fCoursesPh':"जैसे CS 1337, CS 4349 (अल्पविराम से अलग करें)",'prof.fTitle':"पद",'prof.fTitlePh':"जैसे प्रोफ़ेसर, डॉ., लेक्चरर",'prof.myPoints':"आपके रिव्यूअर पॉइंट",'prof.pts':"पॉइंट",'prof.ptsToSpec':"स्पेशलिस्ट के लिए {n} पॉइंट",'prof.specEarned':"स्पेशलिस्ट मिला 🌟",'prof.dupProf':"यह प्रोफ़ेसर पहले से सूची में हैं — रेट करने के लिए उन्हें खोजें।"});

