Object.assign(HUB.i18n._dict('en'),{'bdg.title':"Profile badges",'bdg.sub':"Badges are earned by showing up — each day you spend at least a minute in Onaro counts as one qualifying login day.",'bdg.note':"Badges live on this device only for now — syncing across devices arrives with the full Onaro backend.",'bdg.new':"NEW",'bdg.newD':"Welcome to Onaro! Every login day moves you closer to Silver.",'bdg.silver':"SILVER",'bdg.silverD':"90 qualifying login days. You are officially part of the orbit.",'bdg.gold':"GOLD",'bdg.goldD':"180 qualifying login days. A veteran of the community.",'bdg.legend':"LEGEND",'bdg.legendD':"365 qualifying login days — a full year of showing up. Legendary.",'bdg.specialist':"SPECIALIST",'bdg.specialistD':"1,000 reviewer points. Stacks with your tier badge.",'bdg.nextTier':"{n}/{goal} login days to {next}",'bdg.maxTier':"Max tier reached — you are a LEGEND 🏆",'bdg.specNeed':"{n}/{goal} reviewer points to SPECIALIST",'bdg.specDone':"SPECIALIST earned — 1,000 reviewer points 🌟",'bdg.earnT':"Badge unlocked!",'bdg.viewAll':"View all badges",'bdg.whyTier':"You completed {n} active logins.",'bdg.whySpec':"You earned 1,000 reviewer points.",'bdg.nextT':"What's next",'bdg.nextTierNeed':"{n} more daily logins to {next}",'bdg.nextSpecNeed':"{n} more reviewer points to SPECIALIST",'bdg.tipLogin':"Open Onaro for at least a minute every day — each day counts as one login.",'bdg.tipReview':"Rate and review your professors in the Professors tab — every review earns 10 points.",'bdg.tipAddProf':"Know a professor who's missing? Add them for 25 points.",'notif.sys.badges':"Badges"});
Object.assign(HUB.i18n._dict('es'),{'bdg.title':"Insignias de perfil",'bdg.sub':"Las insignias se ganan apareciendo: cada día que pasas al menos un minuto en Onaro cuenta como un día de inicio válido.",'bdg.note':"Las insignias viven solo en este dispositivo por ahora — la sincronización entre dispositivos llegará con el backend completo de Onaro.",'bdg.new':"NUEVO",'bdg.newD':"¡Bienvenido a Onaro! Cada día de inicio te acerca a Plata.",'bdg.silver':"PLATA",'bdg.silverD':"90 días de inicio válidos. Ya eres oficialmente parte de la órbita.",'bdg.gold':"ORO",'bdg.goldD':"180 días de inicio válidos. Un veterano de la comunidad.",'bdg.legend':"LEYENDA",'bdg.legendD':"365 días de inicio válidos — un año entero apareciendo. Legendario.",'bdg.specialist':"ESPECIALISTA",'bdg.specialistD':"Más de 100 reseñas de profesores escritas. Se suma a tu insignia de nivel.",'bdg.nextTier':"{n}/{goal} días de inicio para {next}",'bdg.maxTier':"Nivel máximo alcanzado — eres una LEYENDA 🏆",'bdg.specNeed':"{n}/{goal} reseñas de profesores para ESPECIALISTA",'bdg.specDone':"ESPECIALISTA conseguida — más de 100 reseñas de profesores 🌟",'bdg.earnT':"¡Insignia desbloqueada!",'bdg.viewAll':"Ver todas las insignias",'bdg.whyTier':"Completaste {n} inicios de sesión activos.",'bdg.whySpec':"Publicaste tu reseña número 100 de un profesor.",'bdg.nextT':"Qué sigue",'bdg.nextTierNeed':"{n} inicios diarios más para {next}",'bdg.nextSpecNeed':"{n} reseñas de profesores más para ESPECIALISTA",'bdg.tipLogin':"Abre Onaro al menos un minuto cada día — cada día cuenta como un inicio.",'bdg.tipReview':"Califica y reseña a tus profesores en la pestaña Profesores — cada reseña cuenta.",'notif.sys.badges':"Insignias"});
Object.assign(HUB.i18n._dict('ne'),{'bdg.title':"प्रोफाइल ब्याजहरू",'bdg.sub':"ब्याजहरू उपस्थितिबाट कमाइन्छ — Onaro मा कम्तीमा एक मिनेट बिताएको प्रत्येक दिन एउटा योग्य लगइन दिन मानिन्छ।",'bdg.note':"ब्याजहरू अहिले यसै डिभाइसमा मात्र रहन्छन् — पूर्ण Onaro ब्याकएन्डसँग डिभाइसहरूबीच सिङ्क हुनेछ।",'bdg.new':"नयाँ",'bdg.newD':"Onaro मा स्वागत छ! प्रत्येक लगइन दिनले तपाईंलाई सिल्भरतिर लैजान्छ।",'bdg.silver':"सिल्भर",'bdg.silverD':"९० योग्य लगइन दिन। तपाईं आधिकारिक रूपमा कक्षाको हिस्सा हुनुहुन्छ।",'bdg.gold':"गोल्ड",'bdg.goldD':"१८० योग्य लगइन दिन। समुदायका अनुभवी।",'bdg.legend':"लिजेन्ड",'bdg.legendD':"३६५ योग्य लगइन दिन — पूरै एक वर्ष उपस्थिति। लिजेन्डरी।",'bdg.specialist':"स्पेशलिस्ट",'bdg.specialistD':"१००+ प्राध्यापक समीक्षा लेखिएको। तपाईंको टियर ब्याजसँगै देखिन्छ।",'bdg.nextTier':"{next} का लागि {n}/{goal} लगइन दिन",'bdg.maxTier':"अधिकतम टियर पुगियो — तपाईं लिजेन्ड हुनुहुन्छ 🏆",'bdg.specNeed':"स्पेशलिस्टका लागि {n}/{goal} प्राध्यापक समीक्षा",'bdg.specDone':"स्पेशलिस्ट प्राप्त — १००+ प्राध्यापक समीक्षा 🌟",'bdg.earnT':"ब्याज अनलक भयो!",'bdg.viewAll':"सबै ब्याजहरू हेर्नुहोस्",'bdg.whyTier':"तपाईंले {n} सक्रिय लगइन पूरा गर्नुभयो।",'bdg.whySpec':"तपाईंले आफ्नो १००औँ प्राध्यापक समीक्षा पोस्ट गर्नुभयो।",'bdg.nextT':"अर्को के",'bdg.nextTierNeed':"{next} का लागि {n} थप दैनिक लगइन",'bdg.nextSpecNeed':"स्पेशलिस्टका लागि {n} थप प्राध्यापक समीक्षा",'bdg.tipLogin':"हरेक दिन कम्तीमा एक मिनेट Onaro खोल्नुहोस् — प्रत्येक दिन एउटा लगइन मानिन्छ।",'bdg.tipReview':"प्राध्यापक ट्याबमा आफ्ना प्राध्यापकहरूलाई मूल्याङ्कन र समीक्षा गर्नुहोस् — प्रत्येक समीक्षा गणना हुन्छ।",'notif.sys.badges':"ब्याजहरू"});
Object.assign(HUB.i18n._dict('hi'),{'bdg.title':"प्रोफ़ाइल बैज",'bdg.sub':"बैज उपस्थिति से मिलते हैं — Onaro में कम से कम एक मिनट बिताया गया हर दिन एक योग्य लॉगिन दिवस गिना जाता है।",'bdg.note':"बैज फ़िलहाल सिर्फ़ इसी डिवाइस पर रहते हैं — डिवाइसों के बीच सिंक पूर्ण Onaro बैकएंड के साथ आएगा।",'bdg.new':"नया",'bdg.newD':"Onaro में स्वागत! हर लॉगिन दिवस आपको सिल्वर के करीब ले जाता है।",'bdg.silver':"सिल्वर",'bdg.silverD':"90 योग्य लॉगिन दिवस। आप आधिकारिक रूप से ऑर्बिट का हिस्सा हैं।",'bdg.gold':"गोल्ड",'bdg.goldD':"180 योग्य लॉगिन दिवस। समुदाय के दिग्गज।",'bdg.legend':"लेजेंड",'bdg.legendD':"365 योग्य लॉगिन दिवस — पूरे साल की उपस्थिति। लेजेंडरी।",'bdg.specialist':"स्पेशलिस्ट",'bdg.specialistD':"100+ प्रोफ़ेसर समीक्षाएँ लिखीं। आपके टियर बैज के साथ दिखता है।",'bdg.nextTier':"{next} के लिए {n}/{goal} लॉगिन दिवस",'bdg.maxTier':"अधिकतम टियर पहुँच गया — आप लेजेंड हैं 🏆",'bdg.specNeed':"स्पेशलिस्ट के लिए {n}/{goal} प्रोफ़ेसर समीक्षाएँ",'bdg.specDone':"स्पेशलिस्ट मिला — 100+ प्रोफ़ेसर समीक्षाएँ 🌟",'bdg.earnT':"बैज अनलॉक हुआ!",'bdg.viewAll':"सभी बैज देखें",'bdg.whyTier':"आपने {n} सक्रिय लॉगिन पूरे किए।",'bdg.whySpec':"आपने अपनी 100वीं प्रोफ़ेसर समीक्षा पोस्ट की।",'bdg.nextT':"आगे क्या",'bdg.nextTierNeed':"{next} के लिए {n} और दैनिक लॉगिन",'bdg.nextSpecNeed':"स्पेशलिस्ट के लिए {n} और प्रोफ़ेसर समीक्षाएँ",'bdg.tipLogin':"हर दिन कम से कम एक मिनट के लिए Onaro खोलें — हर दिन एक लॉगिन गिना जाता है।",'bdg.tipReview':"प्रोफ़ेसर टैब में अपने प्रोफ़ेसरों को रेट करें और समीक्षा लिखें — हर समीक्षा मायने रखती है।",'notif.sys.badges':"बैज"});

