'askg.capsule.s4':"उस तारीख़ को या उसके बाद ऐप खोलते ही यह अपने आप अनलॉक हो जाएगा।",
'askg.badges.t':"बैज",
'askg.badges.d':"NEW, SILVER, GOLD, LEGEND और SPECIALIST कमाएँ।",
'askg.badges.q':"मैं बैज कैसे कमाऊँ?",
'askg.badges.s1':"अपने बैज देखने के लिए Me टैब खोलें।",
'askg.badges.s2':"रोज़ Onaro कम से कम एक मिनट खोलें — हर दिन एक योग्य लॉगिन दिन गिना जाएगा।",
'askg.badges.s3':"आगे बढ़ें: NEW → SILVER (90 दिन) → GOLD (180) → LEGEND (365)।",
'askg.badges.s4':"100+ प्रोफेसर समीक्षाएँ लिखकर SPECIALIST भी पाएँ।",
'askg.verify.t':"सत्यापन",
'askg.verify.d':"Onaro पर खाते कैसे सत्यापित होते हैं।",
'askg.verify.q':"मैं अपना खाता कैसे सत्यापित करूँ?",
'askg.verify.s1':"हर Onaro खाता सत्यापित होना चाहिए — कोई अपवाद नहीं।",
'askg.verify.s2':"अपने फ़ोन नंबर (देश कोड के साथ) और ईमेल से साइन अप करें।",
'askg.verify.s3':"ईमेल कोड या SMS कोड — दोनों में से किसी एक से सत्यापित करें, एक ही काफ़ी है।",
'askg.verify.s4':"फिर अपने नंबर या ईमेल से लॉग इन करें।",
'askg.settings.t':"सेटिंग्स",
'askg.settings.d':"भाषा, थीम, देश, नोटिफ़िकेशन।",
'askg.settings.q':"सेटिंग्स कहाँ हैं?",
'askg.settings.s1':"Me टैब खोलें और Settings पर टैप करें।",
'askg.settings.s2':"भाषा बदलें (28 भाषाएँ), डार्क/लाइट थीम बदलें, या अपना देश चुनें।",
'askg.settings.s3':"उसी जगह से नोटिफ़िकेशन प्रबंधित करें।",
'askg.settings.s4':"इस प्रीव्यू में सब कुछ आपके डिवाइस पर रहता है — कुछ भी अपलोड नहीं होता।",
'askg.events.t':"इवेंट्स",
'askg.events.d':"देखें आस-पास क्या हो रहा है — या खुद आयोजित करें।",
'askg.events.q':"मैं इवेंट्स कैसे खोजूँ?",
'askg.events.s1':"Daily टैब खोलें और Happening पर टैप करें।",
'askg.events.s2':"अपने आस-पास क्या चल रहा है, देखें।",
'askg.events.s3':"विवरण के लिए किसी इवेंट पर टैप करें।",
'askg.events.s4':"कुछ आयोजित कर रहे हैं? Daily टैब से अपना इवेंट बनाएँ।"
