'wel.a12':'Shower or bathe daily; mild, unscented soap is enough. Bathing during your period is completely fine.',
'wel.a13':'Wear breathable cotton underwear and change promptly if it feels damp.',
'wel.a14':'Keep a small period kit for school or work: spare protection, wipes, and anything that comforts you.',
'wel.a15':'Eat balanced meals and drink water through the day to steady your energy.',
'wel.a2T':'Easing cramps & finding comfort',
'wel.a21':'Heat helps: a warm water bottle or heating pad on your lower belly relaxes muscles.',
'wel.a22':'Gentle movement — walking, stretching, light yoga — can ease pain over time.',
'wel.a23':'Rest when you need it; needing extra sleep during your period is normal.',
'wel.a24':'Warm drinks like ginger or chamomile tea can be soothing.',
'wel.a25':'Slow deep breathing and relaxation can lower how intense pain feels.',
'wel.a26':'If pain is severe, getting worse, or regularly stops you living normally, talk to a healthcare professional.',
'wel.a3T':'PMS & mood',
'wel.a31':'Mood dips before a period are common — be kind to yourself on low days.',
'wel.a32':'Keep sleep regular; tiredness makes everything feel harder.',
'wel.a33':'Magnesium and B6-rich foods (nuts, bananas, whole grains) help some people.',
'wel.a34':'Small comforts count: gentle movement, journaling, music, time with people you trust.',
'wel.a35':"If low mood feels overwhelming or doesn't lift, consider speaking with a qualified healthcare professional.",
'wel.a4T':'Heavy or long periods — know the facts',
'wel.a41':'Educational fact: a period lasting longer than 7 days is considered heavy bleeding.',
'wel.a42':'Soaking through a pad or tampon every hour for several hours in a row is a sign to get checked.',
'wel.a43':'Passing clots larger than a quarter, or needing to change protection at night, also count as heavy.',
'wel.a44':'Common problems people report: fatigue, weakness, dizziness, shortness of breath — heavy bleeding can lower iron.',
'wel.a45':'Self-care basics: track your flow, rest, eat iron-rich foods, and stay hydrated.',
'wel.a46':'Seek care promptly for: soaking a pad/tampon an hour for 2+ hours in a row, bleeding between periods, or fainting with bleeding.',
'wel.a47':"Treatments exist — heavy periods are not something you simply have to live with.",

