/* comida y dieta */
'wel.foodT':'Planes de alimentación y dieta',
'wel.foodSub':'Ideas de nutrición según cada fase de tu ciclo.',
'wel.foodNote':'Información general de bienestar, no es consejo médico.',
'wel.phMen':'Menstrual','wel.phMenD':'Días 1–5 · durante el sangrado',
'wel.phFol':'Folicular','wel.phFolD':'Días 6–13 · energía en aumento',
'wel.phOvu':'Ovulación','wel.phOvuD':'Alrededor de la mitad del ciclo',
'wel.phLut':'Lútea','wel.phLutD':'Antes de tu próximo periodo',
'wel.now':'Ahora',
'wel.eatMore':'Prioriza',
'wel.limit':'Limita',
'wel.mealIdeas':'Ideas de comidas sencillas',
'wel.fMen1':'Alimentos ricos en hierro: espinacas, lentejas, frijoles, carne roja magra — el hierro ayuda a reponer lo que se pierde con el sangrado.',
'wel.fMen2':'Combina el hierro con vitamina C (cítricos, pimientos, tomate) para ayudar a absorberlo.',
'wel.fMen3':'Comidas cálidas y fáciles: sopas, caldos, sopa de lentejas, khichdi.',
'wel.fMen4':'Alimentos con magnesio: semillas de calabaza, nueces, un poco de chocolate oscuro — pueden aliviar los calambres.',
'wel.fMen5':'Tés de hierbas reconfortantes: jengibre o manzanilla.',
'wel.lMen1':'Exceso de cafeína y alcohol — pueden empeorar la fatiga y los calambres.',
'wel.lMen2':'Snacks muy salados — pueden aumentar la hinchazón.',
'wel.mMen1':'Sopa de espinacas y lentejas con un toque de limón.',
'wel.mMen2':'Avena caliente con dátiles y nueces.',
'wel.mMen3':'Té de jengibre con khichdi o arroz con dal.',
'wel.fFol1':'Proteínas magras: huevos, pollo, pescado, tofu, legumbres.',
'wel.fFol2':'Verduras frescas y coloridas.',
'wel.fFol3':'Grasas saludables: aguacate, aceite de oliva, nueces.',
'wel.fFol4':'Granos integrales y alimentos fermentados como el yogur.',
'wel.fFol5':'Cítricos y bayas.',
'wel.lFol1':'Bebidas muy azucaradas — suben y bajan tu energía.',
'wel.lFol2':'Saltarte comidas — el combustible constante mantiene la energía estable.',
'wel.mFol1':'Tortilla de verduras con pan integral.',
'wel.mFol2':'Pollo o pescado a la plancha con ensalada grande.',
'wel.mFol3':'Yogur con bayas y linaza.',
'wel.fOvu1':'Verduras ricas en fibra: brócoli, coliflor, kale, repollo.',
'wel.fOvu2':'Frutas antioxidantes: bayas y cítricos.',
'wel.fOvu3':'Omega-3: salmón, nueces, linaza.',
'wel.fOvu4':'Mucha agua, además de alimentos hidratantes como pepino y sandía.',
'wel.fOvu5':'Huevos y proteína magra para una energía estable.',
'wel.lOvu1':'Exceso de alcohol.',
'wel.lOvu2':'Fritos muy pesados y grasosos.',
'wel.mOvu1':'Salmón con verduras.',
'wel.mOvu2':'Ensalada de bayas y aguacate.',
'wel.mOvu3':'Agua de pepino y menta con un bowl ligero de proteína.',
'wel.fLut1':'Carbohidratos complejos: camote, arroz integral, avena — energía estable para los antojos.',
'wel.fLut2':'Magnesio: un poco de chocolate oscuro, plátano, nueces, semillas.',
'wel.fLut3':'Calcio: lácteos o alternativas fortificadas.',
'wel.fLut4':'Verduras de hoja verde más proteína en cada comida.',
'wel.fLut5':'Té de hierbas caliente por la noche.',
'wel.lLut1':'Exceso de cafeína — puede alterar el sueño y el ánimo.',
'wel.lLut2':'Comidas muy saladas — pueden empeorar la hinchazón.',
'wel.mLut1':'Camote con dal y verduras.',
'wel.mLut2':'Avena nocturna con plátano y nueces.',
'wel.mLut3':'Té de manzanilla con un trozo pequeño de chocolate oscuro.',
'wel.dietT':'Tu plan de dieta para el periodo',
'wel.d1':'Come alimentos ricos en hierro los días de sangrado, con vitamina C al mismo tiempo.',
'wel.d2':'Bebe agua durante el día — los líquidos tibios también cuentan.',
'wel.d3':'Come a horas regulares; saltarte comidas puede empeorar la fatiga y el ánimo.',
'wel.d4':'Para los calambres, a muchas personas les alivia el té de jengibre, las sopas calientes y los alimentos con magnesio.',
'wel.d5':'Para la hinchazón ayudan el agua y alimentos con potasio como el plátano; modera la sal.',
'wel.d6':'Limita el exceso de cafeína, alcohol y comidas muy saladas durante tu periodo.',
/* centro de conocimiento */
'wel.hubT':'Centro de conocimiento de bienestar',
'wel.hubSub':'Guías cortas y prácticas para cuidarte.',
'wel.a1T':'Cuidarte durante tu periodo',
'wel.a11':'Cambia toallas, tampones o copas cada 4–8 horas — nunca uses protección mucho más tiempo del recomendado.',
'wel.a12':'Dúchate o báñate a diario; un jabón suave sin perfume es suficiente. Bañarte durante el periodo está perfectamente bien.',
'wel.a13':'Usa ropa interior de algodón transpirable y cámbiala pronto si se humedece.',
'wel.a14':'Lleva un pequeño kit para la escuela o el trabajo: protección de repuesto, toallitas y lo que te reconforte.',
'wel.a15':'Come comidas equilibradas y bebe agua durante el día para mantener tu energía.',
'wel.a2T':'Aliviar calambres y encontrar consuelo',
'wel.a21':'El calor ayuda: una botella de agua caliente o almohadilla térmica en el bajo vientre relaja los músculos.',
'wel.a22':'El movimiento suave — caminar, estirar, yoga ligero — puede aliviar el dolor con el tiempo.',
'wel.a23':'Descansa cuando lo necesites; necesitar más sueño durante el periodo es normal.',
'wel.a24':'Las bebidas calientes como el té de jengibre o manzanilla pueden reconfortar.',
'wel.a25':'La respiración lenta y profunda y la relajación pueden reducir la intensidad del dolor.',
'wel.a26':'Si el dolor es intenso, empeora o te impide vivir con normalidad, habla con un profesional de la salud.',
'wel.a3T':'SPM y ánimo',
'wel.a31':'Los bajones de ánimo antes del periodo son comunes — sé amable contigo en los días difíciles.',
'wel.a32':'Mantén un sueño regular; el cansancio hace que todo se sienta más difícil.',
'wel.a33':'Los alimentos con magnesio y B6 (nueces, plátano, granos integrales) ayudan a algunas personas.',
'wel.a34':'Los pequeños consuelos cuentan: movimiento suave, escribir, música, tiempo con personas de confianza.',
'wel.a35':'Si el ánimo bajo se siente abrumador o no mejora, considera hablar con un profesional de la salud calificado.',
'wel.a4T':'Periodos abundantes o largos — conoce los datos',
'wel.a41':'Dato educativo: un periodo que dura más de 7 días se considera sangrado abundante.',
'wel.a42':'Empapar una toalla o tampón cada hora durante varias horas seguidas es señal de que debes consultar.',
'wel.a43':'Expulsar coágulos más grandes que una moneda de 25 centavos, o necesitar cambiarte de noche, también cuenta como abundante.',
'wel.a44':'Problemas comunes que reportan las personas: fatiga, debilidad, mareos, falta de aire — el sangrado abundante puede bajar el hierro.',
'wel.a45':'Cuidados básicos: registra tu flujo, descansa, come alimentos con hierro y mantente hidratada.',
'wel.a46':'Busca atención pronto si: empapas una toalla/tampón por hora durante 2+ horas seguidas, sangras entre periodos o te desmayas con el sangrado.',
'wel.a47':'Existen tratamientos — los periodos abundantes no son algo que simplemente debas soportar.',

