'wel.d1':'रगत बग्ने दिनहरूमा आइरनयुक्त खाना खानुहोस्, साथमा भिटामिन C।',
'wel.d2':'दिनभर पानी पिउनुहोस् — तातो तरल पनि हुन्छ।',
'wel.d3':'नियमित छाक खानुहोस्; छाक छोड्दा थकान र मनोदशा बिग्रन सक्छ।',
'wel.d4':'पेट दुखाइमा धेरैलाई अदुवा चिया, तातो सुप र म्याग्नेसियमयुक्त खानाले आराम दिन्छ।',
'wel.d5':'पेट फुल्दा पानी र केराजस्ता पोटासियमयुक्त खाना सहयोगी; नुन कम गर्नुहोस्।',
'wel.d6':'महिनावारीमा धेरै क्याफिन, रक्सी र धेरै नुनिलो खाना सीमित गर्नुहोस्।',
