'wel.hubT':'स्वास्थ्य ज्ञान केन्द्र',
'wel.hubSub':'आफ्नो हेरचाहका लागि छोटा, व्यावहारिक मार्गनिर्देशन।',
'wel.a1T':'महिनावारीमा आफ्नो हेरचाह',
'wel.a11':'प्याड, ट्याम्पोन वा कप हरेक 4–8 घण्टामा फेर्नुहोस् — सिफारिसभन्दा धेरै लामो समय एउटै नलगाउनुहोस्।',
'wel.a12':'दैनिक नुहाउनुहोस् वा स्नान गर्नुहोस्; हल्का, सुगन्धरहित साबुन पर्याप्त छ। महिनावारीमा नुहाउनु पूर्ण रूपमा ठीक छ।',
'wel.a13':'सास फेर्ने सुती भित्री वस्त्र लगाउनुहोस् र भिजेमा तुरुन्तै फेर्नुहोस्।',
'wel.a14':'स्कुल वा कामका लागि सानो महिनावारी किट राख्नुहोस्: अतिरिक्त सुरक्षा, वाइप्स र आराम दिने कुरा।',
'wel.a15':'ऊर्जा स्थिर राख्न सन्तुलित खाना खानुहोस् र दिनभर पानी पिउनुहोस्।',
'wel.a2T':'पेट दुखाइ कम गर्ने र आराम पाउने',
'wel.a21':'तातोले मद्दत गर्छ: तल्लो पेटमा तातो पानीको बोतल वा हिटिङ प्याडले मांसपेशी खुकुलो पार्छ।',
'wel.a22':'हल्का हिँडडुल — हिँड्ने, तन्किने, हल्का योग — ले समयसँगै दुखाइ कम गर्न सक्छ।',
'wel.a23':'आवश्यक परे आराम गर्नुहोस्; महिनावारीमा बढी निद्रा लाग्नु सामान्य हो।',
'wel.a24':'अदुवा वा क्यामोमाइल चियाजस्ता तातो पेयले आराम दिन सक्छ।',
'wel.a25':'बिस्तारै गहिरो सास फेर्ने र आरामले दुखाइको तीव्रता घटाउन सक्छ।',
'wel.a26':'यदि दुखाइ गम्भीर छ, बढ्दै छ, वा नियमित रूपमा सामान्य जीवनमा बाधा पुर्‍याउँछ भने स्वास्थ्यकर्मीसँग कुरा गर्नुहोस्।',
'wel.a3T':'PMS र मनोदशा',
'wel.a31':'महिनावारीअघि मनोदशा घट्नु सामान्य हो — कठिन दिनहरूमा आफूप्रति दयालु हुनुहोस्।',
'wel.a32':'निद्रा नियमित राख्नुहोस्; थकानले सबै कुरा गाह्रो बनाउँछ।',
'wel.a33':'म्याग्नेसियम र B6 युक्त खाना (बदाम, केरा, सम्पूर्ण अन्न) ले कतिपयलाई मद्दत गर्छ।',
'wel.a34':'साना आरामहरू महत्त्वपूर्ण छन्: हल्का हिँडडुल, जर्नलिङ, संगीत, विश्वासिला मानिससँग समय।',
'wel.a35':'यदि न्यून मनोदशा असह्य लाग्छ वा सुधार हुँदैन भने योग्य स्वास्थ्यकर्मीसँग कुरा गर्ने विचार गर्नुहोस्।',
'wel.a4T':'धेरै वा लामो महिनावारी — तथ्य जान्नुहोस्',
'wel.a41':'शैक्षिक तथ्य: 7 दिनभन्दा लामो महिनावारीलाई धेरै रगत बग्ने मानिन्छ।',
'wel.a42':'लगातार धेरै घण्टासम्म हरेक घण्टा प्याड वा ट्याम्पोन भिज्नु जाँच गराउने संकेत हो।',
'wel.a43':'सिक्काभन्दा ठूला रगतका डल्ला आउनु वा राति फेर्नुपर्नु पनि धेरै बग्नेमा गनिन्छ।',
'wel.a44':'धेरैले बताउने सामान्य समस्या: थकान, कमजोरी, चक्कर, सास फेर्न गाह्रो — धेरै रगत बग्दा आइरन घट्न सक्छ।',
'wel.a45':'आधारभूत हेरचाह: आफ्नो प्रवाह ट्र्याक गर्नुहोस्, आराम गर्नुहोस्, आइरनयुक्त खाना खानुहोस्, पानी पिउनुहोस्।',
'wel.a46':'तुरुन्तै हेरचाह खोज्नुहोस्: लगातार 2+ घण्टा हरेक घण्टा प्याड/ट्याम्पोन भिजेमा, महिनावारीबीच रगत बगेमा, वा रगतसँगै बेहोस भएमा।',
'wel.a47':'उपचारहरू छन् — धेरै महिनावारीलाई सहनैपर्छ भन्ने छैन।',

