'wel.a22':'हल्की हलचल — टहलना, स्ट्रेचिंग, हल्का योग — समय के साथ दर्द कम कर सकता है।',
'wel.a23':'ज़रूरत हो तो आराम करें; पीरियड में ज़्यादा नींद आना सामान्य है।',
