'wel.a34':'छोटे आराम मायने रखते हैं: हल्की हलचल, जर्नलिंग, संगीत, भरोसेमंद लोगों के साथ समय।',
'wel.a35':'यदि उदासी असहनीय लगे या ठीक न हो, तो किसी योग्य स्वास्थ्य पेशेवर से बात करने पर विचार करें।',
'wel.a4T':'भारी या लंबे पीरियड — तथ्य जानें',
'wel.a41':'शैक्षिक तथ्य: 7 दिनों से लंबा पीरियड भारी रक्तस्राव माना जाता है।',
'wel.a42':'लगातार कई घंटों तक हर घंटे पैड या टैम्पोन भीगना जांच कराने का संकेत है।',
'wel.a43':'सिक्के से बड़े खून के थक्के आना, या रात में बदलना पड़ना भी भारी गिना जाता है।',
'wel.a44':'लोगों की आम शिकायतें: थकान, कमज़ोरी, चक्कर, सांस फूलना — भारी रक्तस्राव से आयरन घट सकता है।',
'wel.a45':'बुनियादी देखभाल: अपना प्रवाह ट्रैक करें, आराम करें, आयरन युक्त भोजन लें, पानी पिएं।',
'wel.a46':'तुरंत देखभाल लें यदि: लगातार 2+ घंटे हर घंटे पैड/टैम्पोन भीगे, पीरियड के बीच रक्तस्राव हो, या रक्तस्राव के साथ बेहोशी आए।',
